A.bU4=new B.l("Minor/moderate infections (PO or IV):",A.hjm,null)
A.bF2=new B.d("Child and adult: 20 mg/kg/24 hr \xf7 Q6\u20138 hr",!1)
A.daG=s([A.bF2],t.I)
A.c12=new B.l("Severe infections (PO or IV):",A.daG,null)
A.bor=new B.d("Child: 2\u20134 mg/kg/24 hr PO once daily",!1)
A.hB1=s([A.bor],t.I)
A.c05=new B.l("Urinary tract infection (UTI) prophylaxis:",A.hB1,null)
