A.biV=new B.d("Max. initial dose: 4 g/24 hr",!1)
A.beT=new B.d("Maintenance: 30\u201370 mg/kg/24 hr PO \xf7 Q4\u20138 hr; max. dose: 4 g/24 hr",!1)
