A.dxY=s(["maintenance fluid","fluid","holliday segar","neonatal fluid","iv fluid","fluid requirement","ml per kg","dehydration","fluid therapy","4-2-1 rule","fluid rate","drip rate","normal saline","NS","RL","ringer lactate","D5NS","isolyte","fluid bolus","fluid management","day 1 fluid","preterm fluid"],t.s)
A.nLo=new B.d2(1,"Stage I",A.Y,"Stage I \u2014 excellent prognosis (>90% survival with favourable histology). Nephrectomy plus short chemotherapy.")
A.nL9=new B.d2(2,"Stage II",A.Y,"Stage II \u2014 completely resected beyond the kidney. Chemotherapy without flank radiotherapy in favourable histology.")
A.nL6=new B.d2(3,"Stage III",A.aQ,"Stage III \u2014 residual abdominal disease. Chemotherapy PLUS flank/abdominal radiotherapy.")
