A.bAm=new B.d("Child \u22652 yr: 0.5 mg/kg/dose PO/PR Q12 hr PRN; max. dose: 25 mg/dose",!1)
A.bbm=new B.d("Adult: 25 mg PO Q8\u201312 hr PRN",!1)
