A.c6N=new B.l("ICU sedation:",A.eg6,null)
A.b9q=new B.d("Child (limited data):",!0)
A.brF=new B.d("IV: 2 mCg/kg/dose \xd7 1 followed by 1.5 mCg/kg/hr was administered to children with autism/pervasive developmental disorders for sedation for electroencephalography (EEG).",!1)
A.bGR=new B.d("IM: 1\u20134.5 mCg/kg/dose \xd7 1 was administered to children for sedation for EEG. Extremely anxious, inconsolable, aggressive, and noncompliant children received doses >2.5 mCg/kg, and calm and relatively compliant children received doses \u22642.5 mCg/kg. A second lower repeat dose (\u223c2 mCg/kg/dose) was administered when adequate sedation was not achieved after 10 min of the first dose.",!1)
A.bx2=new B.d("Intranasal route (limited data): 1\u20132 mCg/kg/dose \xd7 1 for premedication 30\u201360 min prior to anesthesia induction",!1)
A.bgs=new B.d("Adult: 0.5\u20131 mCg/kg/dose IV \xd7 1 over 10 min, followed by 0.6 mCg/kg/hr titrated to effect; dosage has ranged from 0.2\u20131 mCg/kg/hr.",!1)
