A.byh=new B.d("Infant \u22651 mo and child (see remarks):",!0)
A.bIR=new B.d("Mild/moderate infections: 100\u2013200 mg/kg/24 hr \xf7 Q6 hr IM/IV; max. dose: 8 g ampicillin/24 hr",!1)
A.blJ=new B.d("Meningitis/severe infections: 200\u2013400 mg/kg/24 hr \xf7 Q4\u20136 hr IM/IV; max. dose: 8 g ampicillin/24 hr",!1)
A.bpa=new B.d("Adult: 1\u20132 g Q6\u20138 hr IM/IV; max. dose: 8 g ampicillin/24 hr",!1)
